(7719111, 1269824, 86447, '<td valign="top">I thought anthology was a collection of writings.   I don''t understand this, but it''s a lovely image.</td>', 'I thought anthology was a collection of writings.   I don''t understand this, but it''s a lovely image.', '2022-04-22 11:54:09.000000', NULL, 1),
(7719127, 1269728, 87808, '<td valign="top">This is pretty!</td>', 'This is pretty!', '2022-04-22 18:34:00.000000', NULL, 1),
(7719259, 1269701, 42733, '<td valign="top">My favorite in this challenge.</td>', 'My favorite in this challenge.', '2022-04-26 16:38:41.000000', NULL, 1),
(7719260, 1269837, 42733, '<td valign="top">In my top three.</td>', 'In my top three.', '2022-04-26 16:38:50.000000', NULL, 1),
(7719261, 1269828, 42733, '<td valign="top">In my top three.</td>', 'In my top three.', '2022-04-26 16:38:58.000000', NULL, 1),
(7719386, 1269819, 36999, '<td valign="top">Hands down the winner for me!</td>', 'Hands down the winner for me!', '2022-04-27 22:09:53.000000', NULL, 1),
(7719397, 1269741, 56502, '<td valign="top">I must admit I didn''t find it too appealing. Very busy with little to focus on, and the relation to science isn''t too obvious to me either.</td>', 'I must admit I didn''t find it too appealing. Very busy with little to focus on, and the relation to science isn''t too obvious to me either.', '2022-04-28 07:20:09.000000', NULL, 1),
(7719406, 1269786, 103142, '<td valign="top">This is really quite beautiful. I have absolutely no idea if it has anything to do with science, but I believe it. And it makes me think science.</td>', 'This is really quite beautiful. I have absolutely no idea if it has anything to do with science, but I believe it. And it makes me think science.', '2022-04-28 21:01:24.000000', NULL, 1),
(7719407, 1269820, 103142, '<td valign="top">Not that interesting of a photo, but fits the challenge beautifully. It seems like putting the items over on the right would make it more interesting -- seeing more of the symtpoms or more of the writing. I think it would stand the test of time a bit more that way. 10 years down the road it would hit home better. Still a 7 for meeting a difficult challenge.</td>', 'Not that interesting of a photo, but fits the challenge beautifully. It seems like putting the items over on the right would make it more interesting -- seeing more of the symtpoms or more of the writing. I think it would stand the test of time a bit more that way. 10 years down the road it would hit home better. Still a 7 for meeting a difficult challenge.', '2022-04-28 21:03:42.000000', NULL, 1),
(7719408, 1269751, 103142, '<td valign="top">8 from me. Fits the challenge nicely, and took a flat, relatively lifeless thought and made it dynamic with placement and angle. Nicely done.</td>', '8 from me. Fits the challenge nicely, and took a flat, relatively lifeless thought and made it dynamic with placement and angle. Nicely done.', '2022-04-28 21:05:49.000000', NULL, 1),
(7719409, 1269835, 103142, '<td valign="top">impressive</td>', 'impressive', '2022-04-28 21:06:06.000000', NULL, 1),
(7719411, 1269819, 103142, '<td valign="top">I do really like this. I like that it looks gritty and used. I like the point of view. And the space walker up in the corner makes it feel a little creepy -- I think we''ve found Major Tom!<br/> <br/>Nicely seen.</td>', 'I do really like this. I like that it looks gritty and used. I like the point of view. And the space walker up in the corner makes it feel a little creepy -- I think we''ve found Major Tom! Nicely seen.', '2022-04-28 21:06:43.000000', NULL, 1),
(7719412, 1269798, 103142, '<td valign="top">I don''t understand what I''m seeing. Have to come back later.</td>', 'I don''t understand what I''m seeing. Have to come back later.', '2022-04-28 22:36:33.000000', NULL, 1),
(7719415, 1269835, 96751, '<td valign="top">That''s quite spectacular! Congrats on the blue!</td>', 'That''s quite spectacular! Congrats on the blue!', '2022-04-29 02:06:20.000000', NULL, 0),
(7719416, 1269701, 96751, '<td valign="top">Beautiful symmetry.</td>', 'Beautiful symmetry.', '2022-04-29 02:06:44.000000', NULL, 0),
(7719417, 1269830, 96751, '<td valign="top">I think everyone has one of these!</td>', 'I think everyone has one of these!', '2022-04-29 02:06:58.000000', NULL, 0),
(7719418, 1269810, 96751, '<td valign="top">This is absolutely fascinating. And the whole "move the entire tribe out", and then "move it back in"... so much work. I marvel at the extraordinary strength in their mandibles. I''ve started tinkering with macro, so kudos, this is wonderful.</td>', 'This is absolutely fascinating. And the whole "move the entire tribe out", and then "move it back in"... so much work. I marvel at the extraordinary strength in their mandibles. I''ve started tinkering with macro, so kudos, this is wonderful.', '2022-04-29 02:09:46.000000', NULL, 0),
(7719419, 1269794, 96751, '<td valign="top">Love the colors!</td>', 'Love the colors!', '2022-04-29 02:10:07.000000', NULL, 0),
(7719420, 1269751, 96751, '<td valign="top">Fun!</td>', 'Fun!', '2022-04-29 02:10:32.000000', NULL, 0),
(7719421, 1269819, 96751, '<td valign="top">Would love to see this someday.</td>', 'Would love to see this someday.', '2022-04-29 02:11:12.000000', NULL, 0),
(7719422, 1269843, 96751, '<td valign="top">Really bucolic landscape</td>', 'Really bucolic landscape', '2022-04-29 02:11:40.000000', NULL, 0),
(7719423, 1269786, 96751, '<td valign="top">Interesting take on the challenge.</td>', 'Interesting take on the challenge.', '2022-04-29 02:12:11.000000', NULL, 0),
(7719424, 1269728, 96751, '<td valign="top">So basically, all your recent images have ended in the top 10....<br/> <br/>Congrats. Both on the placement and getting to the top to see this.</td>', 'So basically, all your recent images have ended in the top 10.... Congrats. Both on the placement and getting to the top to see this.', '2022-04-29 02:13:06.000000', NULL, 0),
(7719427, 1269835, 97225, '<td valign="top">Congrats on the blue. Great fit to the theme and visually very appealing, this was my top pick.</td>', 'Congrats on the blue. Great fit to the theme and visually very appealing, this was my top pick.', '2022-04-29 02:30:39.000000', NULL, 0),
(7719428, 1269701, 21124, '<td valign="top">The pattern, the contrast, the complementary colors...I love it.<br/>Too bad this is slightly tilted. It could have been straightened in post-processing, as editing rules allow for perspective correction.<br/> <br/>Now, the questions are what are we looking at, and how did you managed to have the orange/blue complementary colors?<br/>I guess there are some mirrors involved (an infinity black mirror?), but I have no idea about the colors.</td>', 'The pattern, the contrast, the complementary colors...I love it.Too bad this is slightly tilted. It could have been straightened in post-processing, as editing rules allow for perspective correction. Now, the questions are what are we looking at, and how did you managed to have the orange/blue complementary colors?I guess there are some mirrors involved (an infinity black mirror?), but I have no idea about the colors.', '2022-04-29 02:54:10.000000', NULL, 0),
(7719433, 1269810, 87808, '<td valign="top">I loved this one and it was a Blue in my voting, really fascinating!</td>', 'I loved this one and it was a Blue in my voting, really fascinating!', '2022-04-29 09:59:01.000000', NULL, 0),
